<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 설계 과정</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            background-color: #f0f0f0;
        }
        #canvas {
            width: 100%;
            height: 600px;
            border: 1px solid #ccc;
        }
        .controls {
            position: absolute;
            top: 10px;
            left: 10px;
            background-color: #fff;
            padding: 10px;
            border: 1px solid #ddd;
            border-radius: 5px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
        }
        .controls button {
            margin-bottom: 10px;
        }
        .info {
            position: absolute;
            bottom: 10px;
            left: 10px;
            font-size: 19px;
            color: #333;
        }
    </style>
</head>
<body>
    <canvas id="canvas"></canvas>
    <div class="controls">
        <button id="reset-camera">초기화</button>
        <button id="stage-1">1단계</button>
        <button id="stage-2">2단계</button>
        <button id="stage-3">3단계</button>
        <button id="complete">완료 모델</button>
    </div>
    <div class="info">llama4-scout</div>

    <script src="../runtime/three-runtime.js"></script>
    <script>
        let camera, scene, renderer, controls;
        let stage1, stage2, stage3, completeModel;
        let currentStage = null;

        // Initialize Three.js
        init();

        function init() {
            // Create scene and camera
            scene = new THREE.Scene();
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            camera.position.set(0, 0, 500);

            // Create renderer
            renderer = new THREE.WebGLRenderer({
                canvas: document.getElementById('canvas'),
                antialias: true
            });
            renderer.setSize(window.innerWidth, window.innerHeight);

            // Create OrbitControls
            controls = new THREE.OrbitControls(camera, renderer.domElement);

            // Create models
            createModels();

            // Add event listeners
            document.getElementById('reset-camera').addEventListener('click', resetCamera);
            document.getElementById('stage-1').addEventListener('click', () => showStage(stage1));
            document.getElementById('stage-2').addEventListener('click', () => showStage(stage2));
            document.getElementById('stage-3').addEventListener('click', () => showStage(stage3));
            document.getElementById('complete').addEventListener('click', () => showStage(completeModel));

            // Show initial stage
            showStage(stage1);

            // Handle window resize
            window.addEventListener('resize', onWindowResize);

            // Handle keydown event
            document.addEventListener('keydown', onKeyDown);

            // Reduce motion
            const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
            if (reduceMotion.matches) {
                controls.enableDamping = false;
            }
        }

        function createModels() {
            // Create stage 1
            stage1 = createStage1();

            // Create stage 2
            stage2 = createStage2();

            // Create stage 3
            stage3 = createStage3();

            // Create complete model
            completeModel = createCompleteModel();

            // Add models to scene
            scene.add(stage1);
            scene.add(stage2);
            scene.add(stage3);
            scene.add(completeModel);

            // Hide all models except stage 1
            stage2.visible = false;
            stage3.visible = false;
            completeModel.visible = false;

            // Create diagrams
            createDiagrams();
        }

        function createStage1() {
            // Create a simple box
            const geometry = new THREE.BoxGeometry(100, 100, 100);
            const material = new THREE.MeshBasicMaterial({ color: 0xff0000 });
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(0, 50, 0);
            return mesh;
        }

        function createStage2() {
            // Create a tapered box
            const geometry = new THREE.BoxGeometry(90, 120, 90);
            const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(0, 60, 0);
            return mesh;
        }

        function createStage3() {
            // Create a more tapered box
            const geometry = new THREE.BoxGeometry(80, 150, 80);
            const material = new THREE.MeshBasicMaterial({ color: 0x0000ff });
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(0, 75, 0);
            return mesh;
        }

        function createCompleteModel() {
            // Create a final tapered model
            const geometry = new THREE.BoxGeometry(50, 200, 50);
            const material = new THREE.MeshBasicMaterial({ color: 0xffff00 });
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(0, 100, 0);
            return mesh;
        }

        function createDiagrams() {
            // Create site plan
            const sitePlanGeometry = new THREE.PlaneGeometry(200, 200);
            const sitePlanMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
            const sitePlan = new THREE.Mesh(sitePlanGeometry, sitePlanMaterial);
            sitePlan.rotation.x = -Math.PI / 2;
            sitePlan.position.set(0, -50, 0);
            scene.add(sitePlan);

            // Create typical floor plan
            const floorPlanGeometry = new THREE.PlaneGeometry(50, 50);
            const floorPlanMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
            const floorPlan = new THREE.Mesh(floorPlanGeometry, floorPlanMaterial);
            floorPlan.rotation.x = -Math.PI / 2;
            floorPlan.position.set(0, 20, 0);
            scene.add(floorPlan);

            // Create elevation
            const elevationGeometry = new THREE.PlaneGeometry(200, 300);
            const elevationMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
            const elevation = new THREE.Mesh(elevationGeometry, elevationMaterial);
            elevation.rotation.y = -Math.PI / 2;
            elevation.position.set(-100, 0, 0);
            scene.add(elevation);

            // Create section
            const sectionGeometry = new THREE.PlaneGeometry(200, 300);
            const sectionMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5 });
            const section = new THREE.Mesh(sectionGeometry, sectionMaterial);
            section.rotation.y = Math.PI / 2;
            section.position.set(100, 0, 0);
            scene.add(section);
        }

        function showStage(stage) {
            if (currentStage) {
                currentStage.visible = false;
            }
            stage.visible = true;
            currentStage = stage;
            controls.reset();
            camera.position.set(0, 0, 500);
            camera.lookAt(0, 0, 0);
        }

        function resetCamera() {
            camera.position.set(0, 0, 500);
            camera.lookAt(0, 0, 0);
            controls.reset();
        }

        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }

        function onKeyDown(event) {
            switch (event.key) {
                case 'r':
                    controls.reset();
                    break;
                case '+':
                case '=':
                    camera.zoom += 0.1;
                    camera.updateProjectionMatrix();
                    break;
                case '-':
                    camera.zoom -= 0.1;
                    camera.updateProjectionMatrix();
                    break;
            }
        }

        // Animate
        function animate() {
            requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        }
        animate();
    </script>
</body>
</html>
